    /**
     * Tests getting all SoftwareLoads.
     *
     * @return    Collection
     */
    public List<SoftwareLoad> testGetAll() throws Throwable {
    LOGGER.info( "SoftwareLoadTest:testGetAll() - Retrieving Collection of SoftwareLoads:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all SoftwareLoad : " );
    List<SoftwareLoad> collection  = null;

    try {
        // call the static get method on the SoftwareLoadService
        collection = service.getAllSoftwareLoad();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            SoftwareLoad currEntity  = null;
            Iterator<SoftwareLoad> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getSoftwareLoadId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

